    n = len(g)
    if not n or any(len(row) != n for row in g):
        return g

    full3_rows = [all(v == 3 for v in row) for row in g]
    full3_cols = [all(g[r][c] == 3 for r in range(n)) for c in range(n)]

    def longest_run(flags):
        best = (0, 0)
        start = None
        for i, flag in enumerate(flags + [False]):
            if flag and start is None:
                start = i
            elif not flag and start is not None:
                if i - start > best[0]:
                    best = (i - start, start)
                start = None
        return best

    row_run, col_run = longest_run(full3_rows), longest_run(full3_cols)
    horizontal = row_run[0] >= col_run[0]
    m, band_start = row_run if horizontal else col_run
